0,"Write a Python script that takes a directory path, a prefix string, and a suffix string as command-line arguments. The script should recursively search the directory and all its subdirectories for text files. For each text file found, it should replace all occurrences of the prefix string with the suffix string. The modified content should then be written back to the original file. The script should use standard library functions for file operations and handle potential errors gracefully.",120,,"['```python
import os
import re
import sys
from pathlib import Path

def replace_prefix_suffix(filepath, prefix, suffix):
    try:
        with open(filepath, 'r+') as f:
            content = f.read()
            new_content = re.sub(f'{prefix}', suffix, content)
            f.seek(0)
            f.write(new_content)
            f.truncate()
    except Exception as e:
        print(f""Error while processing {filepath}: {e}"")

def find_textfiles(directory, prefix, suffix):
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.txt'):
                filepath = Path(root) / file
                replace_prefix_suffix(filepath, prefix, suffix)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py [directory] [prefix] [suffix]"")
        sys.exit(1)

    directory = Path(sys.argv[1])
    prefix = sys.argv[2]
    suffix = sys.argv[3]
    find_textfiles(directory, prefix, suffix)
```']",3,[0],[],True,0,0,0,

