import subprocess
import os
import hashlib

def modify_kickstart(config_file_path, parameters):
    # Read existing configuration file
    with open(config_file_path, 'r') as config_file:
        config_content = config_file.read()

    # Define placeholders to be replaced
    placeholders = {**parameters, 'encrypted_password': ''}

    # Replace placeholders in configuration content
    for placeholder_name, placeholder_value in placeholders.items():
        config_content = config_content.replace(placeholder_name, placeholder_value)

    # Encrypt password (for simplicity using SHA-256 hash)
    encrypted_password = encrypt_password('actual_password')

    with open(config_file_path + '_modified', 'w') as modified_config:
        modified_config.write(config_content + '\n' + f'encrypted_password: {encrypted_password}')

def encrypt_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

