import ssl
import hashlib
from neomodel import StructuredNode, StringProperty, RelationshipTo, relationship
from neo4jrestclient import GraphDatabase

def fetch_certificate_from_oauth_request(oauth_url):
    response = requests.get(oauth_url, verify=False)
    response.raise_for_status()
    private_key = response.json()['private_key']
    certificate = response.json()['certificate']

    pem_data = f""{private_key}\n{certificate}""
    return pem_data

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

class User(StructuredNode):
    name = StringProperty(unique_index=True)
    password = StringProperty()

class Item(StructuredNode):
    name = StringProperty(unique_index=True)

class Relationships:
    LIKES = relationship('User', 'LIKES', 'Item')
    CONTAINS = relationship('Item', 'CONTAINS', 'User')

def add_random_graph_elements(graph, num_vertices, num_edges):
    for _ in range(num_vertices):
