        req_data = request.get_json()
        if not req_data:
            abort(400, description=""Invalid input JSON."")

        result = process_data(req_data)
        return jsonify(result)
    except Exception as e:
        return jsonify({""error"": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
