import unittest
from main import app, process_data

class TestMain(unittest.TestCase):
    def setUp(self):
        self.app = app.test_client()

    def test_valid_request(self):
        valid_data = {'key': 'value'}
        response = self.app.post('/api', data=json.dumps(valid_data), content_type='application/json')
        self.assertEqual(response.status_code, 200)
        self.assertIn('value', response.get_json()['key'])

    def test_invalid_request(self):
        response = self.app.post('/api', data='{""key"": value')
        self.assertEqual(response.status_code, 400)
        self.assertTrue('Invalid input JSON.' in response.get_json()['description'])

    def test_failure_in_process_data(self):
        valid_data = {'key': 'value'}
