            with open(path, 'rb') as file:
                hash_obj = hashlib.md5()
                chunk = file.read(8192)
                while chunk:
                    hash_obj.update(chunk)
                    chunk = file.read(8192)
                hashes[path] = hash_obj.hexdigest()
        except FileNotFoundError:
            hashes[path] = ""File not found""
        except Exception as e:
            hashes[path] = str(e)
    return hashes
