0,"Create a Python function that computes the SHA-256 hash for a given directory's contents, including all subdirectories. The function should traverse the directory recursively, read each file's content in chunks, and update the hash using the `hashlib.sha256()` object. Implement error handling for exceptions that may occur during file access or processing. The function should return a dictionary with the hex representation of the SHA-256 hash for each file found within the specified directory.",328,,"[""```python
import os
import hashlib
import sys

def compute_sha256(directory):
    sha = hashlib.sha256()
    error = False

    try:
        for root, dirs, files in os.walk(directory):
            for file in files:
                try:
                    with open(os.path.join(root, file), 'rb') as f:
                        chunk = f.read(8192)
                        while chunk:
                            sha.update(chunk)
                            chunk = f.read(8192)
                except Exception as e:
                    print(f'Error processing {os.path.join(root, file)}: {e}', file=sys.stderr)
                    error = True

        if not error:
            return {os.path.basename(file): sha.hexdigest() for file in files}
        else:
            return None
    except Exception as e:
        print(f'Error accessing {directory}: {e}', file=sys.stderr)
        return None
```""]",100,[0],[],True,0,0,0,

