import re
planets = {'Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune'}

def count_planets(text):
    pattern = r'\b(?:' + '|'.join(planets) + r'\b)'
    words = re.findall(pattern, text.lower(), re.VERBOSE)
    result = {planet: words.count(planet) for planet in planets}
    return result
```

