import androidx.core.content.ContextCompat
import android.os.Bundle

class MainActivity : AppCompatActivity() {

    private val backgroundTask = ""com.example.myapp.BACKGROUND_TASK""
    private lateinit var notificationManager: NotificationManagerCompat

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // Your content here

        registerReceiver(backgroundTaskReceiver, IntentFilter(backgroundTask))

        if (ContextCompat.checkSelfPermission(this, FOREGROUND_SERVICE) != Permission.GRANTED) {
            requestPermissions(arrayOf(FOREGROUND_SERVICE), 1)
        }

        // Set up push notification service
        val intent = Intent(this, PushNotificationReceiver::class.java)
        val pendingIntent = TaskStackBuilder.create(this).run {
            addNextIntentWithParentStack(intent)
            getPendingIntent(1, PendingIntent.FLAG_UPDATE_CURRENT)
        }

        val smallIconId = R.drawable.ic_stat_notification
        notificationManager = NotificationManagerCompat.from(this)
        val channelId = ""com.example.myapp""
        val channelName = ""My App Channel""
        val importance = NotificationManager.IMPORTANCE_DEFAULT
        val mChannel = NotificationChannel(channelId, channelName, importance)
        notificationManager.createNotificationChannel(mChannel)

        val notificationBuilder = NotificationCompat.Builder(this, channelId)
            .setSmallIcon(smallIconId)
            .setContentTitle(""My App"")
            .setContentText(""Background task active"")
            .setContentIntent(pendingIntent)
            .setAutoCancel(true)
        notificationManager.notify(1, notificationBuilder.build())
    }

    private val backgroundTaskReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            if (intent?.action == backgroundTask) {
                // Handle your background task here
            }
        }
    }
}
```

