import secrets
from cryptography.fernet import Fernet

def create_custom_encryption_key(key_length=32, encoding='utf-8'):
    return Fernet.generate_key()

def encrypt_string(message, key, key_length=32, encoding='utf-8'):
    try:
        f = Fernet(key)
        if len(key) != int(key_length):
            raise ValueError(""Key length must be {} characters"".format(key_length))
        encrypted_message = f.encrypt(message.encode(encoding)).decode('utf-8')
        return encrypted_message
    except Exception as e:
        print(""Error during encryption: "", str(e))
        raise e

def decrypt_string(encrypted_message, key, key_length=32, encoding='utf-8'):
    try:
        f = Fernet(key)
        if len(key) != int(key_length):
            raise ValueError(""Key length must be {} characters"".format(key_length))
        decrypted_message = f.decrypt(encrypted_message.encode(encoding)).decode('utf-8')
        return decrypted_message
    except Exception as e:
        print(""Error during decryption: "", str(e))
        raise e
```

