0,"Create a Python function that recursively computes the SHA-256 hash for a given directory's contents, including subdirectories. Read files in chunks, update the hash using `hashlib.sha256()`, and handle exceptions for file access or processing. Return a dictionary with hex representation of the SHA-256 hash for each file found.",328,,"['```python
import os
import hashlib
import sys

def compute_sha256(directory, parent_hash=None):
    result = {}
    if not parent_hash:
        parent_hash = hashlib.sha256(b'').hexdigest()

    for item in os.scandir(directory):
        if item.is_file():
            with open(item.path, 'rb') as f:
                file_hash = hashlib.sha256()
                chunk = f.read(65536)
                while chunk:
                    file_hash.update(chunk)
                    chunk = f.read(65536)
                result[item.name] = file_hash.hexdigest()
        elif item.is_dir():
            sub_hash = compute_sha256(item.path, parent_hash)
            result.update(sub_hash)

    return {parent_directory + '/' + key: value for key, value in result.items()}

def main():
    try:
        directory = sys.argv[1]
        if not os.path.isdir(directory):
            raise ValueError(""Invalid directory path"")
    except IndexError:
        print(""Usage: python script.py <directory>"")
        return
    except ValueError as e:
        print(e)
        return

    sha256_hash = compute_sha256(directory)
    print(sha256_hash)

if __name__ == ""__main__"":
    main()
```']",0,[0],[],True,0,0,0,

