```python
def crc(data: str, poly: int) -> int:
    """"""Calculates the checksum using CRC algorithm""""""
    def extend_byte(byte: int, bit: int) -> int:
        return (bit << 8) | byte

    def reflect(val: int) -> int:
        """"""Reverses the bits of a given integer.""""""
        return ((val & 0x00ff) << 8 | (val >> 8 & 0x00ff) | (val & 0xf000) >> 4 | (val >> 24 & 0x0f)) << 16 | ((val & 0xff00) << 24 | (val >> 16 & 0xff00) | ((val & 0xff0000) >> 32 & 0xff00) << 8 | (val << 16 & 0xffffffff))

    def divide(dividend: int, divisor: int) -> tuple[int, int]:
        """"""Performs long division of two integers.""""""
        quotient, remainder = divmod(dividend, divisor)
        return (quotient, remainder * 2 if remainder & 1 else remainder)

    def polym_eval(poly: int, bit_string: str) -> int:
        """"""Evaluates the given polynomial on a binary string.""""""
        result = 0
        for char in reversed(bit_string):
            result = divide(result, 2)[1] | (char - '0') * pow(poly, len(bit_string) - bin(result)[::-1].rfind('1')) if char == '1' else result
        return result

    data = list(data)
    poly = polym_eval(poly, bin(poly)[2:])

    table = [0] * 256
    for i in range(256):
        table[i] = (i << 1 | 1) if i >= poly else (i << 1)

    current = 0
    for byte in data:
        for _ in range(ord(byte)):
            current = table[(current >> 8) | (current & 0xff) ^ ord(byte)]
    return reflect(current)

