173,"Design a Python script that efficiently parses a given directory for all Python (.py) files and executes their functions in sequence, simulating the behavior of a custom-built virtual environment. The script should gracefully handle errors such as syntax issues, import failures, and exceptions within the functions, ensuring robust error reporting. It should also maintain a log of executed files and any encountered errors for future reference.",319,,"['```python
import os
import sys
import traceback
import logging
from functools import wraps

# Custom decorator to log function executions and exceptions
def log_execution(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            result = func(*args, **kwargs)
            logging.info(f""Executed: {func.__name__}"")
            return result
        except Exception as e:
            error_message = f""Error in {func.__name__}: {e}""
            logging.error(error_message)
            traceback.print_exception(type(e), e, sys.exc_info()[2])
            raise
    return wrapper

# Main function to traverse the directory and execute Python scripts
def run_scripts(directory):
    log_format = ""%(asctime)s - %(levelname)s - %(message)s""
    logging.basicConfig(filename=""script_log.txt"", level=logging.INFO, format=log_format)

    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith("".py""):
                script_path = os.path.join(root, file)
                try:
                    with open(script_path, ""r"") as script:
                        code = compile(script.read(), script_path, ""exec"")
                        exec(code, {""__name__"": ""__main__""})
                except Exception as e:
                    error_message = f""Error in {script_path}: {e}""
                    logging.error(error_message)
                    traceback.print_exception(type(e), e, sys.exc_info()[2])

if __name__ == ""__main__"":
    run_scripts(""."")  # Replace . with the desired directory path to traverse
```
