0,"Create a program to oversee a library's book collection. This software must permit users to incorporate, eliminate, and locate books within the collection. Furthermore, it should feature the ability to categorize the catalog according to various parameters like author's surname, publishing date, or title. Users should be able to engage with the program via a command-line user interface (CLI) using commands like `-a` for adding books, `-r` for removing books, `-s` for searching books by title or author's name, and `-t` for sorting the catalog based on different attributes. The program should adeptly manage errors when operations such as adding duplicate books or attempting to delete nonexistent books are performed.",807,,"['```python
import sys
from typing import Dict, List, Tuple

class Book:
    def __init__(self, title: str, author_name: str, publication_date: str):
        self.title = title
        self.author_name = author_name
        self.publication_date = publication_date

class Library:
    def __init__(self):
        self.books: Dict[str, Book] = {}

    def add_book(self, book: Book) -> None:
        if book.title in self.books:
            print(""Error: Duplicate book."")
        else:
            self.books[book.title] = book

    def remove_book(self, title: str) -> None:
        if title not in self.books:
            print(""Error: Book not found."")
        else:
            del self.books[title]

    def search_book(self, query: str) -> List[Book]:
        results = []
        for book in self.books.values():
            if query in book.title or query in book.author_name:
                results.append(book)
        return results

    def sort_catalog(self, attribute: str) -> None:
        sorted_books = sorted(self.books.values(), key=lambda book: getattr(book, attribute))
        for book in sorted_books:
            print(book.title)

def main():
    library = Library()

    while True:
        command = input(""Enter a command (-a, -r, -s, -t): "").split(""-"")
        if len(command) == 1 or command[0] not in [""-a"", ""-r"", ""-s"", ""-t""]:
            print(""Invalid command."")
        elif command[0] == ""-a"":
            title = input(""Enter book title: "")
            author_name = input(""Enter author's name: "")
            publication_date = input(""Enter publication date (yyyy-mm-dd): "")
            library.add_book(Book(title, author_name, publication_date))
        elif command[0] == ""-r"":
            title = input(""Enter book title to remove: "")
            library.remove_book(title)
        elif command[0] == ""-s"":
            query = input(""Enter search query (title or author's name): "")
            results = library.search_book(query)
            if results:
                for book in results:
                    print(f""{book.title} by {book.author_name}"")
            else:
                print(""No matching books found."")
        elif command[0] == ""-t"":
            attribute = input(""Enter sorting attribute (title, author_name, or publication_date): "")
            library.sort_catalog(attribute)
        else:
            command[1] = command[1].strip()
            if command[1] in [""author_name"", ""publication_date""]:
                library.sort_catalog(command[1])
            else:
                print(""Invalid attribute for sorting."")

if __name__ == ""__main__"":
    main()
```']",0,[0],[],True,0,0,0,

