class Registry:
    def __init__(self):
        self._registry = {}

    def register(self, id, factory_func):
        if not callable(factory_func):
            raise ValueError(f""Invalid factory function for ID: {id}"")
        self._registry[id] = factory_func

    def generate_instance(self, id, **kwargs):
        if id not in self._registry:
            raise KeyError(f""ID not found in registry: {id}"")
        return self._registry[id](**kwargs)

class JSONHandler:
    _registry = Registry()

    @classmethod
    def register_json_class(cls, json_class):
        cls._registry.register(json_class.__name__, json_class.from_json)

    @classmethod
    def generate_json_instance(cls, json_id, **kwargs):
        return cls._registry.generate_instance(json_id, **kwargs)

    @staticmethod
    def to_json(obj):
        import json
        return json.dumps(obj)

    @staticmethod
    def from_json(json_str):
        import json
        return json.loads(json_str)
