0,"Design a Python function that employs recursion to calculate the SHA-256 hash for every file within a specified directory, including its subdirectories. Implement the process by reading files in portions, updating the hash with `hashlib.sha256()`, and manage errors related to file access or processing. The function should output a dictionary, where each entry contains the hexadecimal representation of the SHA-256 hash for each identified file.",328,,"[""```python
import os
import hashlib
from urllib.error import URLError, ContentError

def calculate_file_hashes(directory):
    hashes = {}

    def process_files(path):
        try:
            for name in os.listdir(path):
                file_path = os.path.join(path, name)

                if not os.path.isfile(file_path):
                    process_files(file_path)
                else:
                    with open(file_path, 'rb') as f:
                        hash_obj = hashlib.sha256()
                        for chunk in iter(lambda: f.read(4096), b''):
                            hash_obj.update(chunk)
                        hashes[file_path] = hash_obj.hexdigest()
        except (URLError, ContentError):
            pass

    process_files(directory)
    return hashes
