class MatrixStruct:
    def __init__(self, dimensions: tuple, determinant: float, eigenvectors: List[np.ndarray]):
        self.dimensions = dimensions
        self.determinant = determinant
        self.eigenvectors = eigenvectors

def extractDelimiterCharacter(string: str, limit: int, current_delimiter: str) -> str:
    if len(string) <= limit:
        return string
    delim_index = string.find(current_delimiter)
    if delim_index == -1 or (delim_index < limit and string[delim_index + 1] != current_delimiter):
        return string[:limit]
    else:
        return extractDelimiterCharacter(string[delim_index+1:], limit, current_delimiter)

def create_matrix_array(file_path: str, dimensions_range: tuple, configuration: dict) -> List[MatrixStruct]:
    matrix_array = []
    with open(file_path, newline='') as csvfile:
        reader = csv.reader(csvfile, delimiter=configuration['delimiter'])
        line_count = 0

        for row in reader:
            if line_count == 0:
                # header row
                dimensions = tuple(map(int, row))
            else:
                if line_count < dimensions[0]*dimensions[1]:
                    matrix_data = [list(map(float, col.split(configuration['delimiter']))) for col in row]
                    random_matrix = np.random.uniform(low=-configuration['range_lower'], high=configuration['range_upper'], size=(dimensions[0], dimensions[1]))
                    matrix_data += list(random_matrix.flatten())
                    matrix_array.append(MatrixStruct((dimensions[0], dimensions[1]), np.linalg.det(np.array(matrix_data).reshape(dimensions)), [np.linalg.eig(np.array(matrix_data).reshape(dimensions)[np.newaxis, :])[1]]))
                line_count += 1
    return matrix_array

