import os
import numpy as np
import struct
import sys
from collections import namedtuple
import subprocess

class ExecutionLog:
    def __init__(self):
        self.executed = []
        self.errors = []

def parse_text_file(file_path):
    with open(file_path, 'r') as file:
        data = list(map(float, filter(str.isdigit, file.read().split())))
    return np.array(data)[:-2]  # Take last two elements as averages

def execute_scripts(directory):
    log = ExecutionLog()
    for file in os.listdir(directory):
        if file.endswith("".py""):
            try:
                script_path = os.path.join(directory, file)
                subprocess.run([sys.executable, script_path])
                log.executed.append(file)
            except Exception as e:
                print(f""Error executing {file}: {e}"")
                log.errors.append((file, str(e)))
    return log

def process_files(directory):
    logs = []
    for root, _, files in os.walk(directory):
        if len(files) == 0:
            continue
        script_log = execute_scripts(root)
        data = np.concatenate([parse_text_file(file) for file in sorted(files)])
        scripts_avg = data[-2]
        log_entry = (np.mean(data), scripts_avg, script_log)
        logs.append(log_entry)
    return np.array(logs)

if __name__ == ""__main__"":
    processed_data = process_files(""path_to_your_directory"")
