import os
import numpy as np
import struct
from ast import parse, NodeVisitor
from io import StringIO
import sys
import logging

class ScriptExecutor(NodeVisitor):
    def __init__(self):
        self.functions = {}

    def visit_FunctionDef(self, node):
        self.functions[node.name] = node

    def get_function(self, function_name):
        return self.functions.get(function_name)

def parse_and_execute_script(script_path):
    with open(script_path) as script_file:
        tree = parse(script_file.read())
        executor = ScriptExecutor()
        executor.visit(tree)

        def execute_function(function_name, *args):
            function = executor.get_function(function_name)
            if not function:
                return None
            return eval(compile(function, script_path, 'exec'), globals(), dict(locals(), **dict(zip(function.args, args))))

        try:
            main_func = execute_function('main')
        except Exception as e:
            logging.error(f""Error in script '{script_path}': {str(e)}"")
        else:
            logging.info(f""Executed script '{script_path}' successfully."")

def average(data):
    return np.mean([data[-2], data[-1]]) if len(data) > 1 else None

def process_file(file_path):
    with open(file_path) as file:
        data = []
        for line in file:
            try:
                value = float(line.strip())
                data.append(value)
            except ValueError:
                pass

        averages = [average(data[i:]) for i in range(len(data) - 2, -1, -2)]
    return np.array(averages)

def execute_and_process_files(directory):
    executed_scripts, errors = [], []
    for file in os.listdir(directory):
        if file.endswith("".py""):
            script_path = os.path.join(directory, file)
            try:
                execute_and_process_files._run_script(script_path)
                executed_scripts.append(file)
            except Exception as e:
                logging.error(f""Error while executing script '{file}': {str(e)}"")
                errors.append(file)

    processed_data = np.concatenate([process_file(os.path.join(directory, file)) for file in executed_scripts])
    return processed_data, executed_scripts, errors

execute_and_process_files._run_script = lambda script_path: parse_and_execute_script(script_path)

if __name__ == ""__main__"":
    logging.basicConfig(level=logging.INFO, format=""%(asctime)s - %(message)s"")

    virtualenv_path = ""your-virtualenv""  # Replace this with your virtual environment path
    venv_activate = os.path.join(virtualenv_path, 'bin/activate')
    scripts_directory = ""scripts_folder""  # Replace this with the directory containing .py files

    if os.path.exists(venv_activate):
        with open(venv_activate, 'r') as f:
            venv_activate_command = f.read().strip() + "" source""
        os.system(venv_activate_command)

    processed_data, executed_scripts, errors = execute_and_process_files(scripts_directory)
