import time
import uuid
from random import randint, choice
import sys

def generate_sensor_data(n, data_array):
    if n <= 0:
        return 1, None

    try:
        mac = uuid.UUID(bytes_le=bytearray.fromhex(""DE:AD:BE:EF:CA:FE""))
        data_range = {
            ""temperature"": (20, 30),
            ""humidity"": (40, 60),
            ""pressure"": (900, 1100)
        }

        data_array[:n] = [SensorData(mac.int >> 32 & 0xFFFFFFFF | uuid.uuid4().int, time.time(), *generate_readings(data_range)) for _ in range(n)]
    except Exception as e:
        return 1, None

    return 0, data_array

def generate_readings(data_range):
    def random_within(lower, upper):
        return (lambda: uniform(lower, upper))() if lower < upper else lambda: lower

    return tuple(map(random_within, *zip(*[data_range.values()] * 3)))

class SensorData:
    def __init__(self, sensor_id, timestamp, temperature, humidity, pressure):
        self.sensor_id = sensor_id
        self.timestamp = timestamp
        self.temperature = temperature
        self.humidity = humidity
        self.pressure = pressure
```

