from typing import List, Dict, Union
import sys
import vitualenvwrapper as ve

class DataRecord:
    def __init__(self, key, offsets):
        self.key = key
        self.offsets = offsets

@dataclass
class TextFileAnalyzer:
    input_dir: str
    csv_file: Union[str, None] = None

    def read_text_files(self):
        matches = {}
        for filename in os.listdir(self.input_dir):
            if not filename.endswith('.txt'):
                continue
            with open(os.path.join(self.input_dir, filename), 'r') as f:
                for line in f:
                    match = re.search(r'-?\d+\.\d+', line)
                    if match:
                        key = filename.split('.')[0]
                        if key not in matches:
                            matches[key] = []
                        matches[key].append(float(match.group()))
        return matches

    def parseCSVData(self):
        data = []
        if self.csv_file:
            with open(self.csv_file, 'r') as csvfile:
                reader = csv.DictReader(csvfile)
                for row in reader:
                    key = row['Key']
                    offsets = [float(x) for x in row['Offsets'].split(',')]
                    data.append(DataRecord(key, offsets))
        return data

    def calculateOffsets(self, records: List[DataRecord]):
        for record in records:
            if len(record.offsets) > 1:
                avg_offset = sum(record.offsets[-2:]) / 2
                record.offsets[-1] = avg_offset

    def executePythonScripts(self, scripts_or_dir):
        ve.virtualenv_list().create_environment(path='myvenv', clear=True)
        ve.activate('myvenv')
        try:
            if isinstance(scripts_or_dir, str):
                for root, dirs, files in os.walk(scripts_or_dir):
                    for file in [f for f in files if f.endswith('.py')]:
                        script = os.path.join(root, file)
                        exec(compile(open(script, 'r').read(), script, 'exec'))
            else:
                for script in scripts_or_dir:
                    ve.activate('myvenv')
                    exec(compile(open(script, 'r').read(), script, 'exec'))
        except Exception as e:
            print(f""Error executing script: {e}"")
