import subprocess
import sys
import zipfile

class DataRecord:
    def __init__(self, keys, offsets):
        self.keys = keys
        self.offsets = offsets

def calculateOffsets(record):
    return sum([record.offsets[i] for i in range(-2, -record.keys.__len__())]) / 2

class TextFileAnalyzer:
    def __init__(self, input_directory, csv_file='', virtual_env=''):
        self.input_directory = input_directory
        self.csv_file = csv_file
        self.virtual_env = virtual_env

    def read_text_files(self):
        numerical_data = defaultdict(list)
        for filename in os.listdir(self.input_directory):
            if not filename.endswith('.txt'):
                continue
            with open(os.path.join(self.input_directory, filename), 'r') as file:
                content = file.read()
                for match in re.finditer(r'\b\d+\.\d+|\b\d+', content):
                    numerical_data[filename].append(float(content[match.start(): match.end()]))
        return numerical_data

    def parseCSVData(self):
        if self.csv_file:
            with open(self.csv_file, 'r') as file:
                csv_reader = csv.DictReader(file)
                records = []
                for row in csv_reader:
                    keys = [key for key in row]
                    offsets = [row[key] for key in reversed(rows[:-1])]
                    records.append(DataRecord(keys, offsets))
                average_offsets = [calculateOffsets(record) for record in records]
                return records, average_offsets
        else:
            return None, None

    def executePythonScripts(self):
        if self.virtual_env:
            try:
                process = subprocess.run(['source', self.virtual_env], capture_output=True)
                if process.returncode != 0:
                    raise Exception('Failed to activate virtual environment')
            except Exception as e:
                print(e)
                sys.exit(1)

            script_paths = []
            for root, dirs, files in os.walk(self.input_directory):
                for file in files:
                    if not file.endswith('.py'):
                        continue
                    script_paths.append(os.path.join(root, file))

            for script_path in script_paths:
                try:
                    process = subprocess.run([sys.executable, script_path], capture_output=True)
                    if process.returncode != 0:
                        print(f'Error executing {script_path}')
                except Exception as e:
                    print(e)

