import os
import subprocess
import re
import logging

def parse_file(file_path):
    with open(file_path, 'r') as file:
        lines = file.readlines()
    parsed_data = []
    for line in lines:
        numbers = re.findall(r'\d+(\.\d*)?', line)
        if numbers:
            parsed_data.append([int(num) if num.isdigit() else float(num) for num in numbers])
    return parsed_data

def calculate_averages(data):
    averages = []
    for field in data:
        if len(field) >= 2:
            averages.append(sum(field[-2:]) / len(field[-2:]))
        else:
            logging.warning(f""Insufficient data in field: {field}"")
    return averages

def execute_py_script(script_file, arg=None):
    try:
        result = subprocess.run(['python', script_file, str(arg)], check=True, capture_output=True)
        logging.info(f""Executed script: {script_file}"")
    except subprocess.CalledProcessError as e:
        logging.error(f""Error executing script: {script_file} - {e.stderr.decode('utf-8')}"")

def execute_py_scripts(directory, log_file):
    executed_files = []
    errors = []

    logging.basicConfig(filename=log_file, level=logging.INFO)

    try:
        for script_file in os.listdir(directory):
            if script_file.endswith('.py'):
                full_path = os.path.join(directory, script_file)
                arguments = parse_data(full_path)
                execute_py_script(full_path, arguments)

        return executed_files, errors
    except Exception as e:
        logging.error(f""An error occurred while processing scripts: {e}"")

def main():
