import heapq
from random import randint

class DijkstraNode:
    def __init__(self, id_, weight=0):
        self.id = id_
        self.weight = weight
        self.adjacency_list = []
        self.visited = False
        self.prev_node = None
        self.distance = float('inf')

    def add_neighbor(self, node, weight):
        self.adjacency_list.append((node, weight))

def generate_random_weight(start_, end_, range_):
    return randint(start_, end_) if start_ < end_ else randint(0, abs(start_ - end_) + 1) + min(start_, end_)

def select_random_neighbors(nodes, node_count):
    chosen = set()
    while len(chosen) < node_count:
        candidate = nodes.pop(randint(0, len(nodes)))
        if candidate not in chosen:
            chosen.add(candidate)
    return list(chosen)

def create_random_graph(node_count):
    nodes = [DijkstraNode(i) for i in range(node_count)]
    for node in nodes:
        neighbors = select_random_neighbors(nodes, node_count)
        for neighbor in neighbors:
            weight = generate_random_weight(1, 10, 1)
            node.add_neighbor(neighbor, weight)
    return nodes

def enhanced_function():
    # Create a random graph with specific number of nodes
    nodes = create_random_graph(node_count=5)

    def dijkstra(start):
        queue = [(node.distance, node.id) for node in nodes]
        visited = set()

        while queue:
            _, current_id = heapq.heappop(queue)

            if current_id not in visited:
                current_node = [n for n in nodes if n.id == current_id][0]
                current_node.visited = True
                visited.add(current_id)

                for neighbor, weight in current_node.adjacency_list:
                    if neighbor.id not in visited:
                        new_distance = current_node.distance + weight
                        if new_distance < neighbor.distance:
                            neighbor.distance = new_distance
                            neighbor.prev_node = current_node
                            heapq.heappush(queue, (new_distance, neighbor.id))

    dijkstra(nodes[0])  # Start with the first node
