import os
import subprocess
from typing import List, Tuple

class TextFileAnalyzer:
    def __init__(self, input_dir: str, output_dir: str):
        self.input_dir = input_dir
        self.output_dir = output_dir

    def read_text_files(self) -> List[Tuple[str, List[int]]]:
        data_sets = []
        for filename in os.listdir(self.input_dir):
            if filename.endswith("".txt""):
                file_path = os.path.join(self.input_dir, filename)
                with open(file_path, 'r') as file:
                    lines = file.readlines()
                    numerical_data = [int(line.strip()) for line in lines]
                    average_data = self.calculate_averages(numerical_data)
                    data_sets.append((filename, average_data))
        return data_sets

    @staticmethod
    def calculate_averages(data_list: List[int]) -> Tuple[int, int]:
        if len(data_list) < 2:
            return 0, 0
        return sum(data_list[-2:]) // 2

    def execute_python_scripts(self, script_directory: str) -> None:
        try:
            subprocess.run([""python"", ""-m"", ""venv"", ""venv""], cwd=script_directory)
            subprocess.run([""source"", ""venv/bin/activate""], cwd=script_directory)
            script_files = [f for f in os.listdir(script_directory) if f.endswith('.py')]
            for script_file in script_files:
                subprocess.run([""python"", script_file], cwd=os.path.join(script_directory))
        except Exception as e:
            print(f""An error occurred while executing scripts: {e}"")
        finally:
            subprocess.run([""deactivate""], cwd=script_directory)

def main():
    input_directory = ""/path/to/input/directory""
    output_directory = ""/path/to/output/directory""
    text_analyzer = TextFileAnalyzer(input_directory, output_directory)

    parsed_data_sets = text_analyzer.read_text_files()

    print(""Parsed Data Sets:"")
    for data_set in parsed_data_sets:
        print(f""Filename: {data_set[0]}, Averages: {data_set[1]}"")

    script_directory_to_execute = ""/path/to/scripts/directory""
    text_analyzer.execute_python_scripts(script_directory_to_execute)

if __name__ == ""__main__"":
    main()
