import json
import csv
from typing import List, Dict

def process_books(json_data: str, genres: List[str] = None) -> None:
    data = json.loads(json_data)
    books_by_year = {}

    for book in data:
        if genres and book[""genre""] not in genres:
            continue

        year = int(book[""publication_year""])
        if year not in books_by_year:
            books_by_year[year] = []

        books_by_year[year].append(book)

