The tool should handle incorrect argument sequences gracefully, print usage instructions if no valid arguments are provided, and execute analyses on the specified text files based on user inputs.",121,,"['```python
import argparse
import re
from collections import Counter
from pathlib import Path

def count_lines(filepath):
    with open(filepath) as f:
        return sum(1 for _ in f)

def count_words(filepath):
    with open(filepath) as f:
        words = re.findall(r'\w+', f.read().lower())
        return len(words)

def word_frequency(filepath):
    with open(filepath) as f:
        words = re.findall(r'\b\w+\b', f.read().lower())
        return Counter(words)

def main():
    parser = argparse.ArgumentParser(description=""Analyze text files."")

    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-l', '--lines', nargs=1)
    parser.add_argument('-w', '--words', nargs=1)
    parser.add_argument('-f', '--frequency', nargs=1)
    parser.add_argument('-o', '--output', nargs='?')

    args = parser.parse_args()

    if args.help:
        print(parser.format_help())
        return

    analysis_types = {'lines': count_lines, 'words': count_words, 'frequency': word_frequency}
    input_file, output_file = None, None

    if args.lines or args.words or args.frequency:
        input_file = Path(args.lines[0] if args.lines else args.frequency[0])

    if args.output:
        output_file = Path(args.output)

    if not input_file:
        print(""No analysis specified or input file not provided."")
        parser.print_help()
        return

    result = analysis_types[args.lines or args.words or args.frequency](input_file)

    if output_file:
        with open(output_file, 'w') as f:
            f.write(str(result))
    else:
        print(result)

if __name__ == ""__main__"":
    main()
