0,"Design a software solution that produces a list of distinctive MAC Address Registration Request PDU units for a designated network interface. The program must guarantee that each generated PDU features a unique blend of source and destination MAC addresses, incorporating an iterative process to generate a new PDU if the created address mix has already been included in the list. Incorporate features to authenticate the uniqueness of the generated PDUs, record comprehensive details about each PDU, and furnish unit tests to confirm its accuracy across different situations.",680,,"[' Here's a Python solution using the `uuid` module for generating unique IDs and storing PDUs in a dictionary:

```python
import uuid
from struct import pack, unpack_from

# Define Ethernet header structure
ETH_ADDR_LEN = 6
ETHERTYPE_IEEE8023 = b'\x08\x00'

class MacAddress:
    def __init__(self, addr):
        if len(addr) != ETH_ADDR_LEN:
            raise ValueError(""Invalid MAC address length"")
        self.addr = [int(b) for b in addr]

    def __str__(self):
        return ':'.join([f'{h:02x}' for h in self.addr])

class Ieee80211QosHdr:
    def __init__(self, qfi=0, qoSControl=0):
        self.qFi = qfi
        self.qOsControl = qoSControl

class MACAddressRegistrationPDU:
    def __init__(self, src_mac, dst_mac, hdr, data=b''):
        self.src_mac = MacAddress(src_mac)
        self.dst_mac = MacAddress(dst_mac)
        self.ethernet_hdr = hdr
        self.data = data

    def __hash__(self):
        return hash((self.src_mac, self.dst_mac, self.ethernet_hdr))

    def __eq__(self, other):
        if not isinstance(other, MACAddressRegistrationPDU):
            return False
        return (self.src_mac == other.src_mac and
                self.dst_mac == other.dst_mac and
                self.ethernet_hdr == other.ethernet_hdr)

def generate_ethernet_header(src_mac, dst_mac, ethertype):
    src_mac_bytes = [int(b) for b in src_mac]
    dst_mac_bytes = [int(b) for b in dst_mac]
    eth_hdr = pack('!6s6sH', *src_mac_bytes, *dst_mac_bytes, *ethertype)
    return eth_hdr

def mac_pdu_gen():
    pdu_store = {}
    while True:
        src_mac = MacAddress(str(uuid.UUID(node=int(time.time_ns())).hex[0:6]))
        dst_mac = MacAddress(str(uuid.UUID(node=int(time.time_ns()) + 1).hex[0:6]))
        ethertype = ETHERTYPE_IEEE8023
        hdr = generate_ethernet_header(src_mac, dst_mac, ethertype)
        pdu = MACAddressRegistrationPDU(src_mac, dst_mac, Ieee80211QosHdr(), hdr + b'data')
        if pdu not in pdu_store:
            yield pdu
            pdu_store[pdu] = True

def test_mac_pdu():
    generated_pdus = list(mac_pdu_gen())

    assert len(generated_pdus) >= 2

    # Custom test cases
    custom_test_1 = MACAddressRegistrationPDU(MacAddress('00:11:22:33:44:55'),
                                               MacAddress('66:77:88:99:AA:BB'),
                                               Ieee80211QosHdr(), generate_ethernet_header(...))
    custom_test_2 = MACAddressRegistrationPDU(MacAddress('00:CC:EE:FF:00:11'),
                                               MacAddress('66:77:88:99:AA:BB'),
                                               Ieee80211QosHdr(), generate_ethernet_header(...))

    assert custom_test_1 in generated_pdus
    assert custom_test_2 not in generated_pdus
