2,"Design and implement a function that takes an array of integers as input and returns the median value. The function should be able to handle both even and odd numbers of elements in the array, ensuring accurate calculation of the median. Additionally, incorporate error handling for scenarios where the input array is empty or contains non-integer values.",680,,"['```python
import statistics

def find_median(arr):
    if not arr:
        raise ValueError(""Input array cannot be empty."")
    if any(type(i) != int for i in arr):
        raise TypeError(""All elements of the input array must be integers."")

    sorted_arr = sorted(arr)
    n = len(sorted_arr)

    if n % 2 == 0:
        median = (sorted_arr[n//2 - 1] + sorted_arr[n//2]) / 2
    else:
        median = sorted_arr[(n-1) // 2]

    return median
