import datetime

class MultimediaFile:
    def __init__(self, title, artist, creation_date, file_type):
        self.title = title
        self.artist = artist
        self.creation_date = creation_date
        self.file_type = file_type

    @property
    def filename(self):
        return f""{self.title}_{self.artist}_{self.creation_date}.{self.file_type}""

def create_multimedia_files(num=10):
    files = []
    for _ in range(num):
        title, artist, creation_date = random.choice([""title{}"".format(i) for i in range(1, 5)]), random.choice([""artist{}"".format(i) for i in range(1, 5)]), datetime.datetime.now()
        file_type = random.choice([""mp3"", ""jpg"", ""png""])
        files.append(MultimediaFile(title, artist, creation_date, file_type))
    return files

def url_encoder(url, params):
    encoded_params = [f""{urllib.parse.quote_key(k)}={urllib.parse.quote_plus(v)}"" for k, v in params.items()]
    return f""{url}?{','.join(encoded_params)}""

def save_to_json(files, output_file):
    with open(output_file, ""w"") as outfile:
        json.dump([f.as_dict() for f in files], outfile)

def as_dict(self):
    return {
        ""title"": self.title,
        ""artist"": self.artist,
        ""creation_date"": self.creation_date.strftime(""%Y-%m-%d %H:%M:%S""),
