import time
import random

class MusicGenre:
    def __init__(self, name, sub_genres):
        self.name = name
        self.sub_genres = sub_genres

def NFA_CRC_INDICATION_PDU_T(rx_ue_information_tag, rnti, crc_indication_rel8_tag):
    return {
        'rx_ue_information_tag': rx_ue_information_tag,
        'rnti': rnti,
        'crc_indication_rel8_tag': crc_indication_rel8_tag
    }

def read_integers(lower_bound, upper_bound):
    while True:
        try:
            user_input = int(input())
            if lower_bound <= user_input <= upper_bound:
                return user_input
        except ValueError:
            print(""Please enter an integer."")

def find_largest(array):
    return max(array)

def main():
    genre = MusicGenre('Pop', ['Rock', 'Hip-Hop', 'EDM', 'Reggaeton'])

    if genre.name == '3':
        print(""Random Number Generator (3 second cooldown):"")
        time.sleep(3)

    sub_genres = genre.sub_genres if genre.name != '3' else [read_integers(-2147483647, 2147483647) for _ in range(len(genre.sub_genres))]

    nfa_array = [NFA_CRC_INDICATION_PDU_T(random.randint(0, 9), random.randint(10, 99999), random.randint(0, 9)) for _ in range(len(sub_genres))]
    sorted_nfa_array = sorted(nfa_array, key=lambda x: find_largest(x.values()))

    print(""NFA_CRC_INDICATION_PDU_T generated:"", sorted_nfa_array)

if __name__ == ""__main__"":
    main()
