import os
import numpy as np
import struct
import argparse
from collections import deque
from multiprocessing import Pool

# Define NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T = namedtuple('NFAPI_CRC_INDICATION_PDU_T', 'crcFlag, msgType, numOfDataFields, dataFields')

def generate_random_crcflag():
    return (np.random.randint(0, 256), np.random.randint(0, 256))

def create_nfa_pi_pdu_array(filename, count=1):
    _, ext = os.path.splitext(filename)
    ext_digits = int(ext[1:]) if ext else None
    modified_ext = f""{ext_digits + 1}.txt"" if ext else ""0.txt""
    output_file = filename[:-len(ext)] + modified_ext

    def _create_struct():
        with open(filename, 'rb') as file:
            crcFlag, msgType, numOfDataFields, *dataFields = struct.unpack('<2IHH' + ('H' * numOfDataFields), file.read())
            return NFAPI_CRC_INDICATION_PDU_T(*([generate_random_crcflag()] + list(zip(crcFlag, msgType, numOfDataFields, dataFields))))

    structures = [_create_struct() for _ in range(count)]
    if count > 1:
        with Pool() as pool:
            structures = pool.map(_create_struct, [output_file] * count)
    return structures

def parse_text_files():
    def _extract_numbers(line):
        numbers = []
        for match in re.findall('\d+', line):
            numbers.append(int(match))
        return numbers

    def _calculate_average(numbers, n=2):
        window = deque(maxlen=n)
        for number in numbers:
            window.append(number)
            if len(window) == n:
                yield sum(window) / n

    for filename in sorted(os.listdir('.'), key=lambda x: int(x[len(x)-5:])):
        structures = create_nfa_pi_pdu_array(filename)
        avg_dataFields = list(_calculate_average(structures[i].dataFields[-2:] for i in range(len(structures))))
        # ... process the averages further, execute .py files, etc.

def run_scripts():
    script_dirs = ['path/to/directory1', 'path/to/directory2']
    interpreter = Interpreter(script_dirs)
    interpreter.run()

class Interpreter:
    def __init__(self, directories):
        self.directories = directories
        self.executed_files = set()
        self.error_log = []

    def run(self):
        for directory in self.directories:
            for filename in os.listdir(directory):
                filepath = os.path.join(directory, filename)
                if not filename.endswith('.py'):
                    continue
                if filename in self.executed_files:
                    continue
                try:
                    with open(filepath) as f:
                        exec(compile(f.read(), filepath, 'exec'), globals())
                except SyntaxError as e:
                    self.error_log.append((filename, str(e)))
                except ImportError as e:
                    self.error_log.append((filename, str(e)))
                except Exception as e:
                    self.error_log.append((filename, str(e)))
                finally:
                    self.executed_files.add(filename)
