struct Point {
    let x: Double
    let y: Double
}

func generateRandomPoints(inRectangle rect: (x1: Double, y1: Double, x2: Double, y2: Double), numPoints: Int) -> [Point] {
    var points = [Point]()
    for _ in 0..<numPoints {
        let x = Double.random(in: rect.x1...rect.x2)
        let y = Double.random(in: rect.y1...rect.y2)
        let newPoint = Point(x: x, y: y)
        points.append(newPoint)
    }
    return points
}

func main() {
    let rectangle = (x1: 0, y1: 0, x2: 5, y2: 5)
    let numPointsToGenerate = 10
    let randomPoints = generateRandomPoints(inRectangle: rectangle, numPoints: numPointsToGenerate)
    for point in randomPoints {
        print(""\(point.x), \(point.y)"")
    }
}
```

