new_json = dict_to_json(my_dict) # '{""Age"": 30, ""City"": ""New York"", ""Name"": ""John""}'
sorted_json = dict_to_json(my_dict, sort_keys=True) # '{""City"": ""New York"", ""Name"": ""John"", ""Age"": 30}'
